-- ----------------------------
-- Table structure for spectrum_data
-- ----------------------------
DROP TABLE IF EXISTS `spectrum_data`;
CREATE TABLE `spectrum_data`  (
  `id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `task_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务ID',
  `item_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测项ID',
  `spectrum_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '波形图数据JSON',
  `measurement_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '测量时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_item_id`(`item_id`) USING BTREE,
  INDEX `idx_measurement_time`(`measurement_time`) USING BTREE,
  INDEX `idx_task_id`(`task_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '波形图数据表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of spectrum_data
-- ----------------------------

-- ----------------------------
-- Table structure for t_cal_artifacts
-- ----------------------------
DROP TABLE IF EXISTS `t_cal_artifacts`;
CREATE TABLE `t_cal_artifacts`  (
  `id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标准实体物质ID',
  `entity_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标准实体物质名称',
  `category_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标准物ID',
  `characteristic_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '特征值',
  `standard_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标准值',
  `is_delete` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否删除（0未删除1已删除）',
  `create_user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` timestamp NULL DEFAULT NULL,
  `update_time` timestamp NULL DEFAULT NULL,
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `expiry_date` date NULL DEFAULT NULL COMMENT '有效期截止日期',
  `reminder_enabled` tinyint(1) NULL DEFAULT 0 COMMENT '是否启用效期提醒：0-否，1-是',
  `reminder_days` int(11) NULL DEFAULT 2 COMMENT '提前提醒天数（默认2天）',
  `last_reminder_date` date NULL DEFAULT NULL COMMENT '上次提醒日期',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `substance_entities_ibfk_1`(`category_id`) USING BTREE,
  INDEX `idx_expiry_date`(`expiry_date`) USING BTREE,
  INDEX `idx_reminder_enabled_expiry`(`reminder_enabled`, `expiry_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标准物质实体' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_cal_artifacts
-- ----------------------------

-- ----------------------------
-- Table structure for t_cal_std_cats
-- ----------------------------
DROP TABLE IF EXISTS `t_cal_std_cats`;
CREATE TABLE `t_cal_std_cats`  (
  `id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标准物质ID',
  `substance_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标准物质名称',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准物质描述',
  `is_delete` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否删除（0未删除，1已删除）',
  `create_user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_user` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` timestamp NULL DEFAULT NULL,
  `update_time` timestamp NULL DEFAULT NULL,
  `material_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ExtRef' COMMENT '标准物类 具体类型（内置物，外部参考物，非标准外部参考物）',
  `characteristic_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '特征值',
  `standard_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标准值',
  `standard_unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标准值单位',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标准物质表类型表' ROW_FORMAT = DYNAMIC;

